'use strict';
const lang=document.documentElement.lang,li={kk:0,ru:1,en:2}[lang]||0,t=(...a)=>a[li],$=s=>document.querySelector(s),esc=s=>String(s??'—').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c])),fmt=(v,n=2)=>Number(v).toLocaleString({kk:'kk-KZ',ru:'ru-RU',en:'en-US'}[lang],{maximumFractionDigits:n});
const isImbalanced=document.body.dataset.lab==='imbalanced';
const lessonAsset=isImbalanced?'imbalanced':'unsupervised';
const downloadBase=isImbalanced?'imbalanced-files/Imbalanced_Data_Lab':'unsupervised-files/Unsupervised_Full_Lab';
const lessonPages=isImbalanced?[8,9]:[1,2,3,4,5,6,7,9];
const chapterHref=id=>'#'+(isImbalanced?lessonPages.indexOf(id)+1:id);
const topicsHref='index'+(lang==='kk'?'':'.'+lang)+'.html#topics';
const colors=['#319b7c','#a18bd0','#d69a49','#648fca','#d07789','#85a341','#ca7850','#46a8b1'];
const names=[t('Деректер','Данные','Data'),'K-Means',t('K таңдау','Выбор K','Choosing K'),'PCA',t('Клиенттер','Клиенты','Customers'),'DBSCAN / Hierarchy','t-SNE',t('Теңгерімсіз деректер','Дисбаланс классов','Imbalanced data'),t('Толық код','Полный код','Full code')];
const headings=[t('Дайын жауапсыз заңдылық іздеу','Ищем структуру без готовых ответов','Discover structure without labels'),t('Нүктелер орталықтарға қалай жиналады?','Как точки собираются вокруг центров?','How do points find their centres?'),t('Неше кластер қажет?','Сколько кластеров выбрать?','How many clusters?'),t('Көп белгіні аз өлшемге сыйғызу','Много признаков — меньше измерений','Project many features into fewer dimensions'),t('2240 клиенттің ұқсастықтары','Сходства между 2240 клиентами','Patterns across 2,240 customers'),t('Топтарды басқа жолмен табу','Находим группы другими способами','Find groups with different assumptions'),t('Жақын нүктелердің картасы','Карта ближайших соседей','A map of local neighbours'),t('90% дәлдік қашан жеткіліксіз?','Когда точности 90% недостаточно?','When is 90% accuracy not enough?'),t('Бүкіл зертхана бір кодта','Вся лабораторная в одном коде','The complete lab in one script')];
const explain=[
t('Бақылаусыз оқытуда дайын y жауабы берілмейді. Кластерлеу ұқсас нысандарды топтайды; PCA мен t-SNE оларды аз өлшемде көрсетеді. new.csv: 2240 жол, 29 бастапқы баған. Табыс бағанында 24 бос мән бар: олар медианамен толтырылады. Алты сандық белгі қолданылады. ID, Response және категориялық бағандар модельге кірмейді. Бұл — бүкіл деректерді зерттеу, сондықтан болжам дәлдігі мен train/test бағасы есептелмейді.','В обучении без учителя нет готового ответа y. Кластеризация группирует похожие объекты, PCA и t-SNE уменьшают размерность. В new.csv 2240 строки и 29 исходных столбцов. 24 пропуска Income заполняются медианой. Используем шесть числовых признаков; ID, Response и категории исключены. Это исследование всего набора, поэтому здесь нет test accuracy.','Unsupervised learning has no target y. Clustering groups similar objects; PCA and t-SNE provide lower-dimensional views. new.csv has 2,240 rows and 29 original columns. We impute 24 missing Income values with the median. Six numerical features are used; ID, Response and categorical columns are excluded. This is exploratory analysis of the full dataset, not a train/test prediction benchmark.'),
t('K — топ саны. Әуелі бастапқы орталықтар таңдалады. Әр нүкте ең жақын орталыққа бекітіледі; содан кейін орталық өз тобындағы нүктелердің орташа орнына көшеді. Осы екі қадам қайталанады. Қадам батырмасын бас немесе анимацияны қос. Графикке басып жаңа нүкте қоса аласың. Reset бастапқы 180 нүктені қайтарады. Бұл оқу алгоритмі браузерде нақты есептеледі; бастапқы орталықтары Python кодында да бірдей.','K — число групп. Точки назначаются ближайшему центру, затем центр перемещается в среднюю позицию своей группы. Эти шаги повторяются. Нажимайте «Шаг», запускайте анимацию или добавляйте точки щелчком по графику. Reset возвращает 180 исходных точек. Учебный алгоритм рассчитывается в браузере; Python использует те же начальные центры.','K is the number of groups. Assign each point to its nearest centre, then move each centre to its group mean. Repeat these steps. Step through, play the animation or click the plot to add a point. Reset restores the original 180 points. This educational algorithm runs in the browser; Python uses the same initial centres.'),
t('Inertia — нүктелердің өз орталығынан квадратталған қашықтықтарының қосындысы. K өскенде ол көбіне азаяды, сондықтан ең аз мәнді ғана таңдау жеткіліксіз. Elbow — төмендеу баяулайтын иілім. Silhouette −1 мен 1 аралығында: жоғары мән топтардың жақсы бөлінгенін білдіреді. Мұнда silhouette 500 бірдей кездейсоқ клиентте есептелген. Бұл accuracy емес және жалғыз дұрыс K бар деген сөз емес.','Inertia — сумма квадратов расстояний до центров. При росте K она обычно падает, поэтому одного минимума недостаточно. Elbow — изгиб, после которого снижение замедляется. Silhouette лежит от −1 до 1; больше означает лучшее разделение. Здесь оценка сделана на одной фиксированной выборке из 500 клиентов. Это не accuracy и не доказательство единственного правильного K.','Inertia sums squared distances to centres and generally decreases as K rises. Look for an elbow where improvement slows. Silhouette ranges from −1 to 1; higher indicates better separation. Here it is evaluated on the same fixed sample of 500 customers. It is not accuracy and does not prove that one K is uniquely correct.'),
t("Бұл бетте new.csv файлындағы 2240 клиенттің алты белгісі қолданылады. PCA ең көп өзгергіштік бар жаңа бағыттарды табады: PC1, PC2 және т.б. Компонент санын 1–6 аралығында өзгерт: сақталған дисперсия да өзгереді. 3–6 компонент таңдағанда график алғашқы екеуін ғана көрсетеді. Масштабтау қосылғанда белгілер салыстырмалы масштабқа келеді; екі компонент шамамен 70,70% дисперсия сақтайды. Бұл болжам дәлдігі емес. Түстер — таңдалған масштабтағы алты белгімен есептелген K-Means (K=5) топтары. PCA өзі топтарға бөлмейді. Табыстың шектен тыс мәндері сақталған.","Здесь используются шесть признаков всех 2240 клиентов из new.csv. PCA находит новые направления наибольшей изменчивости: PC1, PC2 и далее. Меняйте число компонент от 1 до 6 и смотрите сохранённую дисперсию. При 3–6 компонентах график показывает только первые две. После стандартизации два компонента сохраняют около 70,70% дисперсии. Это не точность прогноза. Цвета — группы K-Means (K=5), рассчитанные по шести признакам в выбранном масштабе. Сам PCA не кластеризует. Выбросы дохода сохранены.","This page uses six features for all 2,240 customers from new.csv. PCA finds directions of maximum variation: PC1, PC2 and so on. Change the component count from 1 to 6 to inspect retained variance. With 3–6 components, the plot still shows only the first two. After standardization, two components retain about 70.70% of variance, not prediction accuracy. Colours are K-Means groups (K=5) fitted on all six features at the selected scale. PCA itself does not cluster. Income outliers are retained."),
t('K-Means алты белгіге сүйенеді: табыс, соңғы сатып алудан өткен күн, алты өнімге жалпы шығын және web/store/catalog сатып алу сандары. График — сол алты белгінің PCA проекциясы ғана. Масштабтауды өшірсең, үлкен сандары бар Income қашықтыққа басым әсер етеді. Шектен тыс табыс мәндері сақталған: өте кішкентай топ пайда болса, соны тексер. Топ атаулары дайын клиент кластары емес; оларды кестедегі орташа көрсеткіштер арқылы түсіндіреміз.','K-Means использует шесть признаков: доход, давность покупки, суммарные траты и количества web/store/catalog покупок. График — лишь PCA-проекция этих признаков. Без масштабирования Income доминирует в расстоянии. Выбросы дохода сохранены: проверяйте очень маленькие группы. Номера кластеров — условные метки, смысл определяем по средним показателям.','K-Means uses six features: income, recency, total spending and web/store/catalog purchase counts. The plot is only a PCA projection. Without scaling, large Income values dominate distance. Income outliers are retained, so investigate tiny groups. Cluster numbers are arbitrary labels; interpret them through their mean feature values.'),
t('DBSCAN eps радиусындағы көршілерді санайды. min_samples санына нүктенің өзі де кіреді. Тығыз аймақтар топ құрайды, ал −1 белгісі — шу. Радиус тым аз болса шу көбейеді; тым үлкен болса топтар қосылады. Иерархиялық әдіс жақын топтарды біртіндеп біріктіреді. Single ең жақын жұпты, complete ең алыс жұпты, Ward ішкі квадраттық ауытқудың өсуін қолданады. Екі әдіс бірдей 180 жасанды нүктеде көрсетілген.','DBSCAN считает соседей в радиусе eps, включая саму точку в min_samples. Плотные области образуют группы, −1 означает шум. Малый радиус увеличивает шум, большой объединяет группы. Иерархический метод последовательно объединяет группы: single по ближайшей паре, complete по дальней, Ward по приросту внутригрупповой суммы квадратов. Оба метода используют одинаковые 180 синтетических точек.','DBSCAN counts neighbours within eps, including the point itself in min_samples. Dense regions form clusters; −1 denotes noise. Small radii create more noise; large ones merge groups. Hierarchical clustering merges groups using single (nearest pair), complete (furthest pair), or Ward (increase in within-cluster sum of squares) linkage. Both use the same 180 synthetic points.'),
t("Бұл бетте new.csv файлындағы барлық 2240 клиент көрсетіледі. PCA мен t-SNE бірдей алты масштабталған белгіні қолданады: табыс, соңғы сатып алудан өткен күн, жалпы шығын және web/store/catalog сатып алу сандары. t-SNE ұқсас клиенттерді картада жақын ұстауға тырысады. Perplexity көршілік ауқымына әсер етеді: 5, 30, 50 мәндерін салыстыр. Екі графиктегі түстер — алты белгіде есептелген K-Means (K=5) топтары, дайын клиент кластары емес. t-SNE өзі топтарға бөлмейді. Картадағы үлкен арақашықтық пен топтардың ауданын тура мағынада түсіндіруге болмайды. Үш карта Python-да алдын ала есептелген.","Здесь показаны все 2240 клиента из new.csv. PCA и t-SNE используют одни и те же шесть стандартизированных признаков: доход, давность покупки, общие траты и количества покупок web/store/catalog. t-SNE старается сохранить соседство похожих клиентов. Perplexity задаёт масштаб соседства: сравните 5, 30 и 50. Цвета в обоих графиках — группы K-Means (K=5), рассчитанные в пространстве шести признаков, а не известные классы клиентов. t-SNE сам не присваивает кластеры. Большие расстояния и площади групп нельзя трактовать буквально. Три карты заранее рассчитаны в Python.","Both charts show all 2,240 customers from new.csv using the same six standardized features: income, recency, total spending and web/store/catalog purchase counts. t-SNE tries to keep similar customers near each other. Perplexity changes the neighbourhood scale: compare 5, 30 and 50. Colours in both charts are K-Means groups (K=5) fitted in six dimensions, not known customer classes. t-SNE does not assign clusters. Do not interpret global distances or group areas literally. The three maps were precomputed in Python."),
t('Бұл сабақ — бақыланатын классификация. 1000 жасанды мысалдың 90%-ы класс 0, 10%-ы класс 1. Бәріне 0 десек accuracy 90% болады, бірақ сирек класты таппаймыз. Oversampling сирек мысалдарды қайталайды; undersampling көп класты азайтады; SMOTE жақын сирек мысалдардың арасында жаңа нүкте жасайды. Тек train өңделеді, 200 test өзгермейді. Шекті өзгерту — оқу тәжірибесі; ең жақсы шекті test арқылы таңдауға болмайды, оған бөлек validation керек.','Это задача классификации с учителем. Из 1000 примеров 90% относятся к классу 0 и 10% к классу 1. Постоянный ответ 0 даст accuracy 90%, но пропустит редкий класс. Oversampling повторяет редкие объекты, undersampling сокращает частый класс, SMOTE интерполирует соседние редкие объекты. Меняем только train; 200 test неизменны. Порог здесь — учебный эксперимент: выбирать лучший порог нужно на отдельной validation-выборке.','This lesson covers supervised classification: 90% of 1,000 examples are class 0 and 10% class 1. Always predicting 0 yields 90% accuracy but misses every minority example. Oversampling duplicates minority cases, undersampling removes majority cases, and SMOTE interpolates minority neighbours. Only train is resampled; the 200 test cases stay unchanged. Threshold changes are educational; choose a deployment threshold on separate validation data.'),
t('Әр беттегі код сол беттің параметрлерін ескереді. Мұнда барлық бөлімнің бастапқы параметрлері бар толық Python кодын көшіріп немесе notebook жүктеп алуға болады. Colab-та орында: new.csv сайттан автоматты оқылады, ал офлайнда оны кодпен бір бумаға сал. Графиктер Python-да қайта есептеледі.','Код каждой страницы учитывает её текущие параметры. Здесь можно скопировать полный Python-код с исходными параметрами или скачать notebook. В Colab new.csv загружается с сайта; офлайн положите CSV рядом со скриптом. Графики пересчитываются в Python.','Each page code reflects its current parameters. Here you can copy the complete Python script with default parameters or download the notebook. Colab loads new.csv from the site; offline, place the CSV beside the script. Python recomputes the plots.')];
if(isImbalanced)explain[8]=t('Бұл толық код тек теңгерімсіз деректер сабағына арналған. Baseline, oversampling, undersampling, SMOTE және class weight бірге орындалады. Деректер кодта жасалады, CSV қажет емес. Colab notebook, Python немесе ZIP жүктеп алуға болады.','Этот полный код относится только к теме дисбаланса классов. Baseline, oversampling, undersampling, SMOTE и class weight выполняются вместе. Данные создаются в коде, CSV не нужен. Можно скачать Colab notebook, Python или ZIP.','This complete code is for the Imbalanced Data lesson. It runs baseline, oversampling, undersampling, SMOTE and class weights together. Data is generated in the code; no CSV is required. Download the Colab notebook, Python script or ZIP.');
let data,codes,fullCode,page=1,timer=null,step=0,points=[],centers=[],labels=[],phase=0,converged=false;
const state={k:3,ck:5,scale:'scaled',pc:2,ps:'scaled',eps:.2,min:5,hk:2,link:'single',perp:30,method:'base',threshold:.5,row:0,search:''};
function button(id,label){return `<button class="button" id="${id}">${label}</button>`}function slider(id,label,min,max,value,inc=1){return `<label>${label} <output id="${id}Value">${value}</output><input id="${id}" type="range" min="${min}" max="${max}" step="${inc}" value="${value}"></label>`}function select(id,label,options,value){return `<label>${label}<select id="${id}">${options.map(o=>`<option value="${o[0]}" ${String(o[0])===String(value)?'selected':''}>${o[1]}</option>`).join('')}</select></label>`}function stat(value,label){return `<div class="stat-card"><b>${value}</b><span>${label}</span></div>`}function stop(){clearInterval(timer);timer=null}function scales(){return [['scaled',t('Қосулы','Включено','On')],['raw',t('Өшірулі','Выключено','Off')]]}
function reset(){stop();points=data.blobs.map(p=>p.slice());initCenters()}function initCenters(){stop();step=0;phase=0;converged=false;centers=Array.from({length:state.k},(_,i)=>points[Math.floor(i*points.length/state.k)].slice());labels=points.map(()=>-1)}
function assign(){labels=points.map(p=>centers.reduce((best,c,i)=>dist(p,c)<dist(p,centers[best])?i:best,0))}const dist=(a,b)=>a.reduce((s,x,i)=>s+(x-b[i])**2,0);
function advance(){if(converged){stop();return}if(phase===0){assign();phase=1}else{const next=centers.map((c,j)=>{const pp=points.filter((_,i)=>labels[i]===j);return pp.length?[0,1].map(d=>pp.reduce((s,p)=>s+p[d],0)/pp.length):c});converged=next.every((c,i)=>dist(c,centers[i])<1e-12);centers=next;step++;phase=0;if(converged){assign();stop()}}drawK();}
function bounds(xy){return [0,1].map(d=>{const a=xy.map(p=>p[d]),min=Math.min(...a),max=Math.max(...a),pad=(max-min||1)*.12;return [min-pad,max+pad]})}
function plot(id,xy,lab=[],extras='',axis=['X','Y'],fixed){const b=fixed||bounds(xy);const px=p=>[55+(p[0]-b[0][0])/(b[0][1]-b[0][0])*540,365-(p[1]-b[1][0])/(b[1][1]-b[1][0])*320];let s=`<svg class="plot" id="${id}" viewBox="0 0 640 420" role="img" aria-label="${esc(axis.join(' / '))}">`;for(let i=0;i<5;i++){let x=55+i*135,y=365-i*80;s+=`<line x1="55" x2="595" y1="${y}" y2="${y}"/><text x="45" y="${y+4}" text-anchor="end">${fmt(b[1][0]+i*(b[1][1]-b[1][0])/4,1)}</text><text x="${x}" y="386" text-anchor="middle">${fmt(b[0][0]+i*(b[0][1]-b[0][0])/4,1)}</text>`}s+=xy.map((p,i)=>{let [x,y]=px(p);return `<circle data-i="${i}" cx="${x}" cy="${y}" r="${xy.length>500?2.8:4}" fill="${lab[i]===undefined?'#719b88':lab[i]<0?'#87958e':colors[lab[i]%8]}" opacity=".75"><title>#${i+1} · ${fmt(p[0])}, ${fmt(p[1])}${lab[i]!==undefined?' · '+lab[i]:''}</title></circle>`}).join('')+extras+`<text x="325" y="412" text-anchor="middle">${esc(axis[0])}</text><text x="18" y="22">${esc(axis[1])}</text></svg>`;return {html:s,b,px}}
function render(){
  stop();
  const requested=Number(location.hash.slice(1))||1;
  if(!isImbalanced&&requested===8){
    location.replace('imbalanced'+(lang==='kk'?'':'.'+lang)+'.html?lang='+lang+'#1');
    return;
  }
  page=isImbalanced?(requested===2?9:8):(lessonPages.includes(requested)?requested:1);
  const index=lessonPages.indexOf(page),number=String(index+1).padStart(2,'0'),total=String(lessonPages.length).padStart(2,'0');
  $('#chapterNav').innerHTML=lessonPages.map((id,i)=>`<a href="${chapterHref(id)}" ${page===id?'aria-current="page"':''}><span>${String(i+1).padStart(2,'0')}</span>${names[id-1]}</a>`).join('');
  $('#lesson').innerHTML=`<div class="lesson-head"><div><span class="eyebrow">WEEK 10 / ${names[page-1]}</span><h1>${headings[page-1]}</h1><p>${explain[page-1].split('. ')[0]}.</p></div><span class="page-index">${number}<small>/${total}</small></span></div>
  <div class="toolbar">${button('pageCode','&lt;/&gt; '+t('Осы беттің коды','Код этой страницы','Page code'))}${page<9?button('formulaBtn',t('ƒ Формулалар','ƒ Формулы','ƒ Formulas')):''}${button('explainBtn',t('Түсіндірме','Объяснение','Explanation'))}<a class="button" href="${chapterHref(9)}">${t('Толық код','Полный код','Full code')} →</a></div>
  <section class="workspace"><div id="controls" class="experiment-controls"></div><div class="panel-body" id="visual"></div></section>
  ${window.renderLessonFormulas(page,lang,index+1)}
  <section class="explainer" id="explanation"><h2>${t('Түсіндірме','Объяснение','Explanation')}</h2><p>${explain[page-1]}</p></section>
  <div class="next-link"><a class="button" href="${index>0?chapterHref(lessonPages[index-1]):topicsHref}">← ${t('Артқа','Назад','Back')}</a>${index<lessonPages.length-1?`<a class="button primary" href="${chapterHref(lessonPages[index+1])}">${t('Келесі бет','Далее','Next')} →</a>`:''}</div>
  <footer class="source-footer"><span>${t('Негізі: жіберілген 10-апта материалдары','Основа: предоставленные материалы недели 10','Based on the supplied week 10 materials')}</span><a href="https://scikit-learn.org/stable/modules/${isImbalanced?'model_evaluation':'clustering'}.html">scikit-learn ↗</a>${isImbalanced?`<a href="${topicsHref}">${t('Барлық тақырыптар','Все темы','All topics')} →</a>`:'<a href="unsupervised-files/new.csv" download>new.csv ↓</a>'}</footer>`;
  $('#pageCode').onclick=()=>showCode();
  $('#explainBtn').onclick=()=>$('#explanation').scrollIntoView({behavior:'smooth'});
  if(page<9)$('#formulaBtn').onclick=()=>$('#formulas').scrollIntoView({behavior:'smooth'});
  [null,dataPage,kPage,choosePage,pcaPage,customerPage,densityPage,tsnePage,imbalancePage,codePage][page]();
  document.title=names[page-1]+' · ML LAB';
}
function dataPage(){$('#controls').innerHTML=`<label>${t('Іздеу','Поиск','Search')}<input id="dataSearch" type="search" placeholder="ID / Education" value="${esc(state.search)}"></label><a class="button" href="unsupervised-files/new.csv" download>CSV ↓</a>`;$('#dataSearch').oninput=e=>{state.search=e.target.value;state.row=0;drawTable()};drawTable()}
function drawTable(){const rows=data.table.filter(r=>r.join(' ').toLowerCase().includes(state.search.toLowerCase())),start=state.row*12;$('#visual').innerHTML=`<div class="stat-grid">${stat('2240',t('клиент','клиентов','customers'))}${stat('29 → 6',t('бастапқы баған → модель белгісі','столбцов → признаков модели','columns → model features'))}${stat('24',t('Income бос мәні','пропуска Income','missing Income values'))}</div><div class="data-scroll"><table class="data-table"><thead><tr>${data.columns.map(c=>`<th>${esc(c)}</th>`).join('')}</tr></thead><tbody>${rows.slice(start,start+12).map(r=>`<tr>${r.map(v=>`<td>${v===null?'—':esc(v)}</td>`).join('')}</tr>`).join('')}</tbody></table></div><div class="pager">${button('prev','←')}<span>${rows.length?start+1:0}–${Math.min(start+12,rows.length)} / ${rows.length}</span>${button('next','→')}</div>`;$('#prev').disabled=state.row===0;$('#next').disabled=start+12>=rows.length;$('#prev').onclick=()=>{state.row--;drawTable()};$('#next').onclick=()=>{state.row++;drawTable()}}
function kPage(){reset();$('#controls').innerHTML=slider('k','K',2,8,state.k)+button('step',t('Бір қадам','Один шаг','One step'))+button('play','▶ '+t('Анимация','Анимация','Animate'))+button('reset','↺ Reset');$('#k').oninput=e=>{state.k=+e.target.value;$('#kValue').textContent=state.k;initCenters();drawK()};$('#step').onclick=()=>{stop();advance()};$('#play').onclick=()=>{if(timer){stop();$('#play').textContent='▶';return}if(converged)initCenters();timer=setInterval(advance,750);$('#play').textContent='Ⅱ'};$('#reset').onclick=()=>{reset();drawK()};drawK()}
function drawK(){let fixed=[[-3,3],[-3,3]],pl=plot('kplot',points,labels,'',['X₁ (z)','X₂ (z)'],fixed);let extra=centers.map((c,i)=>{let[x,y]=pl.px(c);return `<circle class="centroid" cx="${x}" cy="${y}" r="10" fill="${colors[i]}"><title>C${i+1}</title></circle>`}).join('');let old=$('#kplot');let svg=pl.html.replace('</svg>',extra+'</svg>');const sse=labels[0]>=0?points.reduce((s,p,i)=>s+dist(p,centers[labels[i]]),0):0;
if(!old){$('#visual').innerHTML=`<div class="exp-grid"><div id="plotHost">${svg}</div><div class="exp-side" id="kInfo"></div></div>`}else{const parsed=new DOMParser().parseFromString(svg,'image/svg+xml');const fresh=[...parsed.querySelectorAll('circle')],current=[...old.querySelectorAll('circle')];if(fresh.length===current.length){fresh.forEach((n,i)=>{for(const a of ['cx','cy','r','fill'])current[i].setAttribute(a,n.getAttribute(a));current[i].innerHTML=n.innerHTML})}else $('#plotHost').innerHTML=svg}$('#kInfo').innerHTML=`<span class="eyebrow">LLOYD ALGORITHM / LIVE</span><h3>${converged?t('Орталықтар тұрақталды','Центры стабилизировались','Centres converged'):phase?t('Нүктелер топтарға бекітілді','Точки распределены','Points assigned'):t('Орталықтарды тексер','Проверяем центры','Inspect the centres')}</h3><div class="stat-grid">${stat(step,t('итерация','итерация','iteration'))}${stat(points.length,t('нүкте','точек','points'))}${stat(labels[0]>=0?fmt(sse):'—','SSE')}</div><p>${t('Үлкен шеңберлер — орталықтар. Графикті басып нүкте қос.','Большие круги — центры. Нажмите на график, чтобы добавить точку.','Large circles are centres. Click the plot to add a point.')}</p><div class="cluster-list">${centers.map((c,i)=>`<div class="cluster-row" style="--cluster:${colors[i]}">C${i+1}: ${labels.filter(x=>x===i).length} · (${c.map(v=>fmt(v)).join(', ')})</div>`).join('')}</div>`;$('#kplot').onclick=e=>{const r=e.currentTarget.getBoundingClientRect(),x=(e.clientX-r.left)/r.width*640,y=(e.clientY-r.top)/r.height*420;if(x<55||x>595||y<45||y>365)return;stop();points.push([-3+(x-55)/540*6,-3+(365-y)/320*6]);initCenters();drawK()}}
function choosePage(){$('#controls').innerHTML=slider('ck','K',2,8,state.ck);$('#ck').oninput=e=>{state.ck=+e.target.value;$('#ckValue').textContent=state.ck;drawChoose()};drawChoose()}
function lineChart(values,title){const max=Math.max(...values),min=Math.min(...values),range=max-min||1;return `<svg class="plot" viewBox="0 0 640 310" role="img" aria-label="${title}"><text x="30" y="25">${title}</text><path d="${values.map((v,i)=>`${i?'L':'M'}${65+i*80} ${245-(v-min)/range*180}`).join(' ')}" fill="none" stroke="var(--green)" stroke-width="3"/>${values.map((v,i)=>`<circle cx="${65+i*80}" cy="${245-(v-min)/range*180}" r="${state.ck===i+2?9:5}" fill="${state.ck===i+2?colors[2]:colors[0]}"/><text x="${65+i*80}" y="${230-(v-min)/range*180}" text-anchor="middle">${fmt(v,2)}</text><text x="${65+i*80}" y="280">${i+2}</text>`).join('')}</svg>`}
function drawChoose(){const runs=data.customers.scaled.runs,keys=Object.keys(runs);$('#visual').innerHTML=`<div class="dual-plots">${lineChart(keys.map(k=>runs[k].inertia),'Inertia · StandardScaler')}${lineChart(keys.map(k=>runs[k].silhouette),'Silhouette · n=500')}</div><div class="stat-grid">${stat(state.ck,'K')}${stat(fmt(runs[state.ck].inertia),'Inertia')}${stat(fmt(runs[state.ck].silhouette,3),'Silhouette')}</div><p class="small-note">${t('K-Means: n_init=10, random_state=22. Барлық 2240 клиент, 6 масштабталған белгі.','K-Means: n_init=10, random_state=22. Все 2240 клиента, 6 масштабированных признаков.','K-Means: n_init=10, random_state=22. All 2,240 customers and 6 standardized features.')}</p>`}
function pcaPage(){$('#controls').innerHTML=slider('pc',t('Компонент саны','Компоненты','Components'),1,6,state.pc)+select('ps','StandardScaler',scales(),state.ps);$('#pc').oninput=e=>{state.pc=+e.target.value;$('#pcValue').textContent=state.pc;drawPCA()};$('#ps').onchange=e=>{state.ps=e.target.value;drawPCA()};drawPCA()}
function drawPCA(){const customer=data.customers[state.ps],p=customer.pca,variance=p.variance.slice(0,state.pc).reduce((a,b)=>a+b,0)*100;$('#visual').innerHTML=`<div class="exp-grid"><div>${plot('pcaplot',p.xy.map(r=>[r[0],state.pc>1?r[1]:0]),customer.runs['5'].labels,'',['PC1',state.pc>1?'PC2':'0']).html}<div class="cluster-legend">${customer.runs['5'].sizes.map((n,i)=>`<span><i style="background:${colors[i]}"></i>C${i+1}: ${n}</span>`).join('')}</div></div><div class="exp-side"><span class="eyebrow">new.csv / 2240 × 6</span><h3>6 → ${state.pc}</h3><div class="stat-card"><b>${fmt(variance)}%</b><span>${t('сақталған дисперсия','сохранённая дисперсия','retained variance')}</span></div><div class="progress-bar"><span style="width:${variance}%"></span></div>${p.variance.map((v,i)=>`<div class="cluster-row" style="--cluster:${i<state.pc?colors[0]:'#999'}">PC${i+1}: ${fmt(v*100)}%</div>`).join('')}<p>${t('Түстер: клиенттердің K-Means (K=5) топтары. PCA өзі топ құрмайды. 3–6 компонент таңдағанда график алғашқы екеуін ғана көрсетеді.','Цвета: группы клиентов K-Means (K=5). PCA сам не формирует группы. При 3–6 компонентах график показывает только первые две.','Colours: customer K-Means groups (K=5). PCA does not form groups. With 3–6 components, only the first two are plotted.')}</p></div></div>`}
function customerPage(){$('#controls').innerHTML=slider('ck','K',2,8,state.ck)+select('scale','StandardScaler',scales(),state.scale);$('#ck').oninput=e=>{state.ck=+e.target.value;$('#ckValue').textContent=state.ck;drawCustomers()};$('#scale').onchange=e=>{state.scale=e.target.value;drawCustomers()};drawCustomers()}
function drawCustomers(){let p=data.customers[state.scale],r=p.runs[state.ck];$('#visual').innerHTML=`<div class="stat-grid">${stat('2240',t('клиент','клиентов','customers'))}${stat(fmt(r.silhouette,3),'Silhouette (500)')}${stat(fmt(p.variance.reduce((a,b)=>a+b)*100)+'%','PCA variance')}</div><div class="exp-grid"><div>${plot('customerPlot',p.xy,r.labels,'',['PC1','PC2']).html}</div><div class="cluster-list">${r.sizes.map((n,i)=>`<div class="cluster-row" style="--cluster:${colors[i]}"><strong>C${i+1} · ${n}</strong><small>Income: ${fmt(r.means[i][0],0)} · Spending: ${fmt(r.means[i][2],0)}</small><small>Recency: ${fmt(r.means[i][1],0)} · web/store/catalog: ${r.means[i].slice(3).map(v=>fmt(v,1)).join(' / ')}</small></div>`).join('')}</div></div><p class="small-note">${t('Python-да есептелген модельдер. Белгілер кеңістігі: 6D; көрсетілім: PCA 2D. Табыстың шектен тыс мәндері жойылмаған.','Модели рассчитаны в Python. Обучение в 6D, отображение в PCA 2D. Выбросы дохода не удалены.','Models computed in Python. Fit in 6D; displayed in PCA 2D. Income outliers are retained.')}</p>`}
function dbscan(X,eps,min){let lab=X.map(()=>-2),cluster=0,nei=i=>X.reduce((r,p,j)=>{if(dist(p,X[i])<=eps*eps)r.push(j);return r},[]);for(let i=0;i<X.length;i++){if(lab[i]!==-2)continue;let near=nei(i);if(near.length<min){lab[i]=-1;continue}lab[i]=cluster;let queue=[...near],seen=new Set(queue);for(let q=0;q<queue.length;q++){let j=queue[q];if(lab[j]===-1)lab[j]=cluster;if(lab[j]!==-2)continue;lab[j]=cluster;let ns=nei(j);if(ns.length>=min)ns.forEach(n=>{if(!seen.has(n)){queue.push(n);seen.add(n)}})}cluster++}return lab}
function densityPage(){$('#controls').innerHTML=slider('eps','eps',.05,.7,state.eps,.05)+slider('min','min_samples',2,12,state.min)+slider('hk','Hierarchy K',2,8,state.hk)+select('link','Linkage',[['single','single'],['complete','complete'],['ward','Ward']],state.link);for(const key of ['eps','min','hk'])$('#'+key).oninput=e=>{state[key]=+e.target.value;$('#'+key+'Value').textContent=state[key];drawDensity()};$('#link').onchange=e=>{state.link=e.target.value;drawDensity()};drawDensity()}
function drawDensity(){let lab=dbscan(data.moons,state.eps,state.min),h=data.hierarchy[state.link][state.hk],count=new Set(lab.filter(n=>n>=0)).size;$('#visual').innerHTML=`<div class="dual-plots"><div><h3>DBSCAN · ${count} ${t('топ','групп','clusters')} / ${lab.filter(n=>n===-1).length} ${t('шу','шум','noise')}</h3>${plot('dbplot',data.moons,lab).html}</div><div><h3>Hierarchy · ${state.link} · K=${state.hk}</h3>${plot('hierplot',data.moons,h).html}</div></div><p class="small-note">${t('Сұр нүктелер — шу. DBSCAN браузерде есептеледі; иерархиялық нәтижелер Python-да есептелген.','Серые точки — шум. DBSCAN вычисляется в браузере; иерархические результаты рассчитаны в Python.','Grey points are noise. DBSCAN runs in the browser; hierarchical results were computed in Python.')}</p>`}
function tsnePage(){$('#controls').innerHTML=select('perp','Perplexity',[[5,'5'],[30,'30'],[50,'50']],state.perp);$('#perp').onchange=e=>{state.perp=+e.target.value;drawTSNE()};drawTSNE()}
function drawTSNE(){const customer=data.customers.scaled,labels=customer.runs['5'].labels;$('#visual').innerHTML=`<div class="stat-grid">${stat('2240',t('клиент','клиентов','customers'))}${stat('6',t('масштабталған белгі','стандартизированных признаков','standardized features'))}${stat('5',t('K-Means тобы · түстер','групп K-Means · цвета','K-Means groups · colours'))}</div><div class="dual-plots"><div><h3>PCA · ${fmt(customer.variance.reduce((a,b)=>a+b)*100)}%</h3>${plot('tpca',customer.xy,labels,'',['PC1','PC2']).html}</div><div><h3>t-SNE · perplexity=${state.perp}</h3>${plot('tsne',customer.tsne[state.perp],labels,'',['t-SNE 1','t-SNE 2']).html}</div></div><div class="cluster-legend">${customer.runs['5'].sizes.map((n,i)=>`<span><i style="background:${colors[i]}"></i>C${i+1}: ${n}</span>`).join('')}</div><p class="small-note">new.csv · StandardScaler · random_state=42 · ${t('Екі графикте де бірдей 2240 клиент. Түстер: K-Means (K=5), алты белгіде есептелген.','В обоих графиках одни и те же 2240 клиента. Цвета: K-Means (K=5), рассчитанный по шести признакам.','The same 2,240 customers in both charts. Colours: K-Means (K=5), fitted on six features.')}</p>`}
function imbalancePage(){$('#controls').innerHTML=select('method',t('Әдіс','Метод','Method'),[['base','Baseline'],['over','Oversampling'],['under','Undersampling'],['smote','SMOTE'],['weighted','Class weight']],state.method)+slider('threshold',t('Шек','Порог','Threshold'),0,1,state.threshold,.05);$('#method').onchange=e=>{state.method=e.target.value;drawImbalance()};$('#threshold').oninput=e=>{state.threshold=+e.target.value;$('#thresholdValue').textContent=state.threshold;drawImbalance()};drawImbalance()}
function drawImbalance(){let r=data.imbalance.runs[state.method],cm=[[0,0],[0,0]];r.prob.forEach((v,i)=>cm[data.imbalance.y[i]][v>=state.threshold?1:0]++);let[tn,fp]=cm[0],[fn,tp]=cm[1],prec=tp+fp?tp/(tp+fp):0,rec=tp/(tp+fn),f1=prec+rec?2*prec*rec/(prec+rec):0,sum=r.counts.reduce((a,b)=>a+b);$('#visual').innerHTML=`<div class="stat-grid">${stat(fmt((tp+tn)/2)+'%','Accuracy')}${stat(fmt(rec*100)+'%','Recall · class 1')}${stat(fmt(f1,3),'F1 · class 1')}</div><div class="exp-grid"><div><h3>Train · ${sum}</h3><div class="balancebar">${r.counts.map((n,i)=>`<span style="width:${n/sum*100}%;background:${colors[i]}">${i}: ${n}</span>`).join('')}</div><h3>Test · 200</h3><table class="matrix-small"><caption>${t('Жол — нақты, баған — болжам','Строка — факт, столбец — прогноз','Rows: actual, columns: predicted')}</caption><thead><tr><th></th><th>0</th><th>1</th></tr></thead><tbody><tr><th>0</th><td>${tn}</td><td>${fp}</td></tr><tr><th>1</th><td>${fn}</td><td>${tp}</td></tr></tbody></table></div><div class="exp-side"><h3>${t('Сирек класс — 1','Редкий класс — 1','Minority class = 1')}</h3><p>Precision: ${fmt(prec*100)}%</p><p>${t('Recall: 20 сирек мысалдың қаншасын тапты? F1 precision мен recall-ды бірге бағалайды.','Recall: сколько из 20 редких примеров найдено? F1 объединяет precision и recall.','Recall: how many of the 20 minority cases are found? F1 combines precision and recall.')}</p><p>${t('Test өзгермейді: 180 + 20. Бұл шекті таңдау емес, оның әсерін көрсету.','Test неизменен: 180 + 20. Это демонстрация эффекта порога, не его подбор.','Test stays at 180 + 20. This demonstrates threshold effects, rather than selecting a threshold.')}</p></div></div>`}
function codePage(){$('#controls').innerHTML=`<a class="button primary" href="${downloadBase}.ipynb" download>↓ Colab notebook</a><a class="button" href="${downloadBase}.py" download>↓ Python</a><a class="button" href="${downloadBase}.zip" download>↓ ZIP${isImbalanced?'':' + CSV'}</a>${button('copyFull',t('Көшіру','Копировать','Copy'))}`;$('#visual').innerHTML=`<p class="small-note">${t('Бастапқы параметрлер. Python кодындағы айнымалыларды өзгерте аласың.','Исходные параметры. Переменные можно изменять в Python.','Default parameters. You can edit the variables in Python.')}</p><pre class="code-full"><code>${esc(fullCode)}</code></pre>`;$('#copyFull').onclick=()=>copy(fullCode,$('#copyFull'))}
async function copy(s,b){try{await navigator.clipboard.writeText(s);b.textContent=t('Көшірілді ✓','Скопировано ✓','Copied ✓')}catch(e){const area=document.createElement('textarea');area.value=s;area.style.cssText='position:fixed;left:-9999px';document.body.append(area);area.select();const ok=document.execCommand('copy');area.remove();b.textContent=ok?t('Көшірілді ✓','Скопировано ✓','Copied ✓'):t('Кодты белгілеп көшір','Выделите код и скопируйте','Select and copy the code')}}
function pageCode(){if(page===9)return fullCode;let s=codes[page];if(page===2)s=s.replace('K = 3','K = '+state.k).replace("X = StandardScaler().fit_transform(make_blobs(n_samples=180,centers=3,random_state=23)[0])",'X = np.array('+JSON.stringify(points)+', dtype=float)');if(page===4)s=s.replace('scale=True','scale='+String(state.ps==='scaled')).replace('components=2','components='+state.pc);if(page===5)s=s.replace('K=5','K='+state.ck).replace('scale=True','scale='+String(state.scale==='scaled'));if(page===6)s=s.replace('eps=.2','eps='+state.eps).replace('min_samples=5','min_samples='+state.min).replace('K=2','K='+state.hk).replace("linkage='single'","linkage='"+state.link+"'");if(page===7)s=s.replace('perplexity=30','perplexity='+state.perp);if(page===8)s=s.replace('threshold=.5','threshold='+state.threshold);return s.replace(/scale=true/g,'scale=True').replace(/scale=false/g,'scale=False')}
function showCode(){stop();const s=pageCode();$('#dialogTitle').textContent=names[page-1]+' · Python';$('#dialogBody').innerHTML=`<div class="code-actions">${button('copyCode',t('Көшіру','Копировать','Copy'))}<span class="small-note">${t('Ағымдағы параметрлер · Colab-та жеке орындалады','Текущие параметры · запускается отдельно в Colab','Current parameters · runs independently in Colab')}</span></div><pre><code>${esc(s)}</code></pre>`;$('#copyCode').onclick=()=>copy(s,$('#copyCode'));$('#codeDialog').showModal()}
$('#closeDialog').onclick=()=>$('#codeDialog').close();$('#codeDialog').addEventListener('click',e=>{if(e.target===$('#codeDialog'))$('#codeDialog').close()});window.addEventListener('hashchange',()=>{render();window.scrollTo({top:0,behavior:'instant'})});
Promise.all([fetch(lessonAsset+'-data.json').then(r=>r.json()),fetch(lessonAsset+'-code.json').then(r=>r.json()),fetch(downloadBase+'.py').then(r=>r.text())]).then(([d,c,f])=>{data=d;codes=Object.fromEntries(c.map((s,i)=>[isImbalanced?8:i+1,s]));fullCode=f;render()}).catch(()=>{$('#lesson').innerHTML='<p>'+t('Деректер жүктелмеді. Бетті жаңартыңыз.','Не удалось загрузить данные. Обновите страницу.','Could not load data. Please reload.')+'</p>'});
